from pathlib import Path

_base = Path(__file__).parent / "models"

def pose_predictor_model_location():
    return str(_base / "shape_predictor_68_face_landmarks.dat")

def pose_predictor_five_point_model_location():
    return str(_base / "shape_predictor_5_face_landmarks.dat")

def face_recognition_model_location():
    return str(_base / "dlib_face_recognition_resnet_model_v1.dat")

def cnn_face_detector_model_location():
    return str(_base / "mmod_human_face_detector.dat")
